using Inngest.Signing;
using Microsoft.Extensions.Time.Testing;

namespace Inngest.Tests.Signing;

// The algorithm checked against signatures made by an Inngest server, not against this SDK's own output. The key,
// body and signatures are the vectors in the TypeScript SDK's tests, which were generated by a local server.
public sealed class ServerSignatureTests
{
    // A body as the server canonicalizes it before signing: keys sorted, no whitespace.
    internal const string Body =
        """{"ctx":{"fn_id":"local-testing-local-cron","run_id":"01GQ3HTEZ01M7R8Z9PR1DMHDN1","step_id":"step"},"event":{"data":{},"id":"","name":"demo/event.sent","ts":1674082830001,"v":"1"},"events":[{"data":{},"id":"","name":"demo/event.sent","ts":1674082830001,"v":"1"}],"steps":{},"use_api":false}""";

    internal const string Key = "signkey-test-f00f3005a3666b359a79c2bc3380ce2715e62727ac461ae1a2618f8766029c9f";
    internal const string Header = "t=1687306735&s=a060f245a5d0c3c779ef65fd15b2ac06e4ab98dd8cc9860aa0722c8481ae02ab";
    internal const long SignedAt = 1687306735;

    private const string UnrelatedHeader = "t=1687306735&s=eece58c8cf7cfc21a5751b1969c9aef525c96257b42b556c2782c83d26ea0d87";

    private static readonly byte[] BodyBytes = System.Text.Encoding.UTF8.GetBytes(Body);

    private readonly RequestSigner _signer = new(new FakeTimeProvider(DateTimeOffset.FromUnixTimeSeconds(SignedAt)));

    [Fact]
    public void A_signature_made_by_the_server_verifies()
    {
        var key = SigningKey.Create(Key)!;

        var result = _signer.Verify(Header, BodyBytes, key, fallbackKey: null);

        result.IsValid.ShouldBeTrue();
        result.KeyUsed.ShouldBeSameAs(key);
    }

    [Fact]
    public void A_signature_made_by_the_server_no_longer_verifies_once_it_has_expired()
    {
        var late = new RequestSigner(new FakeTimeProvider(DateTimeOffset.FromUnixTimeSeconds(SignedAt + 3600)));

        late.Verify(Header, BodyBytes, SigningKey.Create(Key)!, fallbackKey: null).IsValid.ShouldBeFalse();
        late.Verify(Header, BodyBytes, SigningKey.Create(Key)!, fallbackKey: null, allowExpired: true).IsValid.ShouldBeTrue();
    }

    [Fact]
    public void The_fallback_key_verifies_the_signature_when_the_current_key_does_not()
    {
        var current = SigningKey.Create("fake")!;
        var fallback = SigningKey.Create(Key)!;

        var result = _signer.Verify(Header, BodyBytes, current, fallback);

        result.IsValid.ShouldBeTrue();
        result.KeyUsed.ShouldBeSameAs(fallback);
    }

    [Theory]
    [InlineData(Header)]
    [InlineData(UnrelatedHeader)]
    public void A_signature_is_rejected_when_neither_key_made_it(string header)
    {
        var result = _signer.Verify(header, BodyBytes, SigningKey.Create("fake")!, SigningKey.Create("another-fake")!);

        result.IsValid.ShouldBeFalse();
        result.KeyUsed.ShouldBeNull();
    }

    [Fact]
    public void A_signature_made_with_another_key_is_rejected_even_though_it_is_well_formed()
    {
        var result = _signer.Verify(UnrelatedHeader, BodyBytes, SigningKey.Create(Key)!, fallbackKey: null);

        result.IsValid.ShouldBeFalse();
    }
}
